style.css:
@-moz-document domain("monopoly-one.com") {
/* In                 --- Setting Tips                --- */
    div.TableHelper-content-options-group
    { width: 108% }

    .form2-row .form2-checkbox label
    { max-width: 58%;
        display: grid !important;
        grid-template-columns: 95% 2%; }

    label[for="table-opt-openCards"]:after
    { content: "";
        display: block;
        height: 8px;
        width: 8px;
        background-color: #95060687;
        margin-left: -7755%;
        border-radius: 50%; }

    label[for="table-opt-profileAction"]:after
    { content: "";
        display: block;
        height: 8px;
        width: 8px;
        background-color: #95060687;
        margin-left: -7755%;
        border-radius: 50%; }

    label[for="table-opt-showRating"]:after
    { content: "";
        display: block;
        height: 8px;
        width: 8px;
        background-color: #95060687;
        margin-left: -7755%;
        border-radius: 50%; }

    label[for="table-opt-showMFP"]:after
    { content: "";
        display: block;
        height: 8px;
        width: 8px;
        background-color: #95060687;
        margin-left: -7755%;
        border-radius: 50%; }

    label[for="table-opt-showFriendship"]:after
    { content: "";
        display: block;
        height: 8px;
        width: 8px;
        background-color: #95060687;
        margin-left: -7755%;
        border-radius: 50%; }

    label[for="table-opt-showGender"]:after
    { content: "";
        display: block;
        height: 8px;
        width: 8px;
        background-color: #95060687;
        margin-left: -7755%;
        border-radius: 50%; }

    label[for="table-opt-showAssets"]:after
    { content: "";
        display: block;
        height: 8px;
        width: 8px;
        background-color: #95060687;
        margin-left: -7755%;
        border-radius: 50%; }

    label[for="table-opt-showShareWorth"]:after
    { content: "";
        display: block;
        height: 8px;
        width: 8px;
        background-color: #95060687;
        margin-left: -7755%;
        border-radius: 50%; }

    label[for="table-opt-showTeamShareWorth"]:after
    { content: "";
        display: block;
        height: 8px;
        width: 8px;
        background-color: #95060687;
        margin-left: -7755% !important;
        border-radius: 50%; }

    /* End                  --- Setting Tips            --- */
    /* In                   --- Core                    --- */
    body[theme=dark] div.games-market-list-one._horizontal, body[theme=dark] div.games-market-list-one
    { background-image: none !important;
        background-color: #26272b !important; }

    span.stats.ion-stats-bars, .VueGamesRoomsOne-body-members-one-stats span::before
    { font-size: 12px !important }

    .games-disconnect-button
    { margin-left: -35px;
        text-align: right; }

    .VueGamesRooms-list
    { display: flex;
        flex-direction: column-reverse; }

    .games-market-list-one._m1pro .games-market-list-one-more-image
    { display: none }

    .table
    { margin-left: -3%; }

    div.header-bans.ion-ios-close, .VueGamesRoomsOne-body-head-info .header-invites
    { background: #eeecec8a;
        border: 10px solid #95959500;
        border-radius: 5px; }

    div.games-market-list-one._m1pro
    { background-image: linear-gradient(162deg, rgb(0, 0, 0) 28%, rgb(220, 20, 60) 130%); }

    .friends-list-one-info-rank .friend_stats, .friends-list-one-info-rank .friend_stats span::before
    { font-size: 13px !important; }

    .friends .friends-list .friends-list-one .friends-list-one-info .friends-list-one-info-nick
    { font-weight: 500;
        font-size: 17px; }

    .friends-list-one-info-rank .friend_stats span::before
    { font-weight: 600;
        margin-top: -2px; }

    body[mnpl-newcolors] .table-body-players-card-body-avatar > div > div
    { border: none }

    body .table-body-players-card-body-avatar > div > div
    { border: 0px solid #161a1b; }

    .table-body-players
    { margin-right: 23px; }

    .table-gameover
    { width: 100% !important; }

    /* End --- Core --- */
    /* In --- Profile Core --- */
    .profile-top
    { margin-left: -12%;
        height: 600px; }

    .profile
    { margin-top: 3%; }

    body:not([theme]) div.title.title-4.profile-body-note-title-text
    { color: #000 }

    .header[mnpl-style=transparent-light] .header-right > div:before
    { color: rgb(91 93 103) !important; }

    .profile-top-stat-badge
    { top: 40% !important;
        right: -8% !important; }

    div.col.profile-body-side
    { margin-right: -14.5%; }

    div.widther.container.profile-body
    { margin-left: 10% }

    div.block.profile-body-inventory
    { width: 1215px;
        margin-left: -30px; }

    .profile-body-inventory-list .Item:not(:first-child)
    { margin-left: 18.1px; }

    .profile-body-inventory-list
    { margin-left: 15px !important; }

    span.newver.m1pro-new-item, .table-body-board-chatbottom.newver::after, .TableHelper-tabs ._settings.newver::after
    { visibility: hidden }

    /* End                  --- Profile Core                --- */
    /* In                   --- Game Board Chat             --- */
    .GchatHistoryUser a ._nick
    { font-weight: 420; }

    .table-body-board-chat-message-users ._arrow
    { background: none !important }

    .table-body-board-chat-message-users ._message._from, .table-body-board-chat-message-users ._message._to, .table-body-board-chat-message-users ._message:not(._hack)
    { font-weight: 500; }

    .table-body-board-chat-message-users ._arrow:after
    { content: "\f215";
        font-size: 16px;
        ;
        padding-top: 1px;
        margin-left: 5px; }

    .table-body-board-chat-message-users ._message._to
    { margin-right: 0px;
        margin-left: 5px;
        border-top-left-radius: 5px;
        border-bottom-left-radius: 5px;
        padding-left: 6px;
        transform: none; }

    .table-body-board-chat-message-users ._message._from
    { margin-left: 2px;
        border-top-right-radius: 5px;
        border-bottom-right-radius: 5px;
        padding-right: 6px;
        margin-right: 8px; }

    /* End                  --- Game Board Chat             --- */
    /* In                   --- Table Helper                --- */
    .table-body-stats .TableHelper-content, .table-body-stats .TablePool-content
    { border-radius: 5px;
        background-color: #212629 !important; }

    div.pool-title
    { padding-top: 10px !important }

    .table-body-players-card-body-info
    { display: none }

    .table-body-board
    { margin-right: 45px; }

    div.Table-body-stats
    { margin-top: 85px;
        height: 80%; }

    .form2-row:not(._nostretch) select.selecter, select.selecter
    { font-family: 'Google Sans';
        width: 100%; }

    div.table-body-players-card-body-income.ion-plus, div.table-body-players-card-body-expenses.ion-minus
    { display: none }

    .ion-scissors:before
    { content: "Счет";
        font-family: 'Google Sans';
        font-size: 10px }

    .ion-stats-bars:before
    { content: "Матчи";
        font-family: 'Google Sans';
        font-size: 10px }

    .ion-pie-graph:before
    { content: "WR";
        font-family: 'Google Sans';
        font-size: 10px }

    /* End                      --- Table Helper                --- */
    /* In                       --- Core                        --- */
    div.table-body-players-card-body-avatar > div
    { width: 177px;
        height: 136.3px;
        border-radius: 1px;
        z-index: 1;
        margin-left: -36px;
        margin-top: -35px }

    body .table-body-players-card-body-avatar > div > div
    { filter: brightness(0.6);
        border: 0px solid #161a1b; }

    .table-body-players-card-body-nick
    { z-index: 5; }

    div.table-body-players-card-body-avatar > div > div
    { border-radius: 0px;
    margin-left: -2px;
    width: 177px;}

    body:not([mnpl-newcolors]) .table-body-players-card-body-avatar > div
    { border: 0px solid transparent;
        border-bottom: 2px solid transparent; }

    .table-body-players-card-body
    { background: none; }

    .table-body-players-card[mnpl-action_player]
    { transform: scale(1.055);
        z-index: 2;
        height: 133.5px; }

    .table-body-players-card[mnpl-action_player] .table-body-players-card-body-avatar > div > div
    { margin-top: 0.3px;
        width: 171.3px; 
        margin-left: 3px;
        border-bottom: 2px solid #262c2f; }

    .VueGamesRoomsOne-body-members-one-stats span.gender
    { display: none; }

    .table-body-players-card-body-timer div, .table-body-players-card-body-timer svg
    { margin-left: -33px;
        margin-top: -30px; }

    div.table-body-players-card-body-show-extra.ion-plus-circled {
    z-index: 9;
    height: 50px;
    width: 100px;
    top: 5px; }

    .ion-plus-circled:before
    { visibility: hidden }

    div.table-body-players-card-body
    { display: grid;
        grid-template-rows: 4fr 1fr; }

    div.table-body-players-card-body-nick
    { width: 157px;
        margin-right: -8px;
        margin-top: 80px; }

    .table-body-players-card-body-nick
    { z-index: 2;
        justify-content: right;
        height: 20px; }

    div.table-body-players-card-body-credit.ion-card
    { font-size: 9.3px; }

    /* End                      --- Core                        --- */
    /* In                       --- Scrollbar                   --- */
    ::-webkit-scrollbar
    { width: 12px;
        left: -2% !important }

    ::-webkit-scrollbar-thumb
    { background-color: #00000045;
        border-radius: 3px;
        left: -2% !important }

    /* End                      --- Scrollbar                   --- */
    /* In                       --- Font                        --- */
    :root, body, input, table
    { font-family: 'Ionicons', 'Google Sans' }

    div.table-body-players-card-body-timer div
    { font-family: 'Ionicons', 'Google Sans' }

    /* cyrillic */
    @font-face
    { font-family: 'Google Sans';
        font-style: normal;
        font-weight: 400;
        font-display: swap;
        src: url(https://fonts.gstatic.com/s/googlesans/v27/4UaGrENHsxJlGDuGo1OIlL3Kwp5MKg.woff2) format('woff2');
        unicode-range: U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116; }

    /* latin-ext */
    @font-face
    { font-family: 'Google Sans';
        font-style: normal;
        font-weight: 400;
        font-display: swap;
        src: url(https://fonts.gstatic.com/s/googlesans/v27/4UaGrENHsxJlGDuGo1OIlL3Awp5MKg.woff2) format('woff2');
        unicode-range: U+0100-024F, U+0259, U+1E00-1EFF, U+2020, U+20A0-20AB, U+20AD-20CF, U+2113, U+2C60-2C7F, U+A720-A7FF; }

    /* latin */
    @font-face
    { font-family: 'Google Sans';
        font-style: normal;
        font-weight: 400;
        font-display: swap;
        src: url(https://fonts.gstatic.com/s/googlesans/v27/4UaGrENHsxJlGDuGo1OIlL3Owp4.woff2) format('woff2');
        unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+2000-206F, U+2074, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD; }

    /* cyrillic */
    @font-face
    { font-family: 'Google Sans';
        font-style: normal;
        font-weight: 500;
        font-display: swap;
        src: url(https://fonts.gstatic.com/s/googlesans/v27/4UabrENHsxJlGDuGo1OIlLU94Yt3CwZ-Pw.woff2) format('woff2');
        unicode-range: U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116; }

    /* latin-ext */
    @font-face
    { font-family: 'Google Sans';
        font-style: normal;
        font-weight: 500;
        font-display: swap;
        src: url(https://fonts.gstatic.com/s/googlesans/v27/4UabrENHsxJlGDuGo1OIlLU94Yt9CwZ-Pw.woff2) format('woff2');
        unicode-range: U+0100-024F, U+0259, U+1E00-1EFF, U+2020, U+20A0-20AB, U+20AD-20CF, U+2113, U+2C60-2C7F, U+A720-A7FF; }

    /* latin */
    @font-face
    { font-family: 'Google Sans';
        font-style: normal;
        font-weight: 500;
        font-display: swap;
        src: url(https://fonts.gstatic.com/s/googlesans/v27/4UabrENHsxJlGDuGo1OIlLU94YtzCwY.woff2) format('woff2');
        unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+2000-206F, U+2074, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD; }

    /* End ---              Font                     --- */
}
